def skill():
    ks = []
    for k in [Rational(1), Rational(2), Rational(5), Rational(6)]:
        ks.append(k)
    # 각 k에 대해 경로 AABA(6), ABAB(2), ABBA(5), BBAB(1) 확인
    def run(k, path):
        a = [k]
        for o in path:
            a.append(a[-1] - 4 if o == 'A' else -2 * a[-1])
        return a
    checks = [(6, 'AABA'), (2, 'ABAB'), (5, 'ABBA'), (1, 'BBAB')]
    for k, p in checks:
        a = run(Rational(k), p)
        assert a[4] == 0 and a[1] * a[2] < 0
    return sum(k * k for k, _ in checks)

def standard():
    k = Symbol('k')
    found = set()
    for path in itertools.product('AB', repeat=4):
        a = [k]
        for o in path:
            a.append(expand(a[-1] - 4 if o == 'A' else -2 * a[-1]))
        for r in solve(Eq(a[4], 0), k):
            if r.is_real and r > 0:
                v = [x.subs(k, r) for x in a]
                if v[1] * v[2] < 0:
                    found.add(r)
    return sum(r * r for r in found)

def unique():
    return [standard()]
